package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen1Test {

    @Test
    public void testCreateNumber_Null() throws NumberFormatException {
        assertNull(NumberUtils.createNumber(null));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_EmptyString() throws NumberFormatException {
        NumberUtils.createNumber("");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_SingleNonDigit() throws NumberFormatException {
        NumberUtils.createNumber("a");
    }

    @Test
    public void testCreateNumber_DoubleDashProtection() throws NumberFormatException {
        assertNull(NumberUtils.createNumber("--"));
    }

    @Test
    public void testCreateNumber_Hexadecimal() throws NumberFormatException {
        // Assumes createInteger handles hex
        assertTrue(NumberUtils.createNumber("0x10") instanceof Integer);
        assertTrue(NumberUtils.createNumber("-0x10") instanceof Integer);
    }

    @Test
    public void testCreateNumber_IntegerTypes() throws NumberFormatException {
        assertTrue(NumberUtils.createNumber("123") instanceof Integer);
        assertTrue(NumberUtils.createNumber("1234567890") instanceof Integer);
        assertTrue(NumberUtils.createNumber("3000000000") instanceof Long);
        assertTrue(NumberUtils.createNumber("9223372036854775807") instanceof Long);
        assertTrue(NumberUtils.createNumber("9223372036854775808") instanceof BigInteger);
    }

    @Test
    public void testCreateNumber_FloatingPointTypes() throws NumberFormatException {
        assertTrue(NumberUtils.createNumber("1.23") instanceof Float);
        assertTrue(NumberUtils.createNumber("1.23e2") instanceof Float);
        assertTrue(NumberUtils.createNumber("1.23E2") instanceof Float);
        assertTrue(NumberUtils.createNumber("1.23456789") instanceof Double);
    }

    @Test
    public void testCreateNumber_BigDecimalFallback() throws NumberFormatException {
        // Force BigDecimal by providing a value that exceeds Double precision or specific formatting
        assertTrue(NumberUtils.createNumber("1.2345678901234567890123456789") instanceof BigDecimal);
    }

    @Test
    public void testCreateNumber_SuffixLong() throws NumberFormatException {
        assertTrue(NumberUtils.createNumber("123L") instanceof Long);
        assertTrue(NumberUtils.createNumber("123l") instanceof Long);
        assertTrue(NumberUtils.createNumber("-123L") instanceof Long);
        // Test BigInteger via Long suffix overflow
        assertTrue(NumberUtils.createNumber("9223372036854775808L") instanceof BigInteger);
    }

    @Test
    public void testCreateNumber_SuffixFloat() throws NumberFormatException {
        assertTrue(NumberUtils.createNumber("1.23f") instanceof Float);
        assertTrue(NumberUtils.createNumber("1.23F") instanceof Float);
    }

    @Test
    public void testCreateNumber_SuffixDouble() throws NumberFormatException {
        assertTrue(NumberUtils.createNumber("1.23d") instanceof Double);
        assertTrue(NumberUtils.createNumber("1.23D") instanceof Double);
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidSuffix() throws NumberFormatException {
        NumberUtils.createNumber("1.23z");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_ExpBeforeDec() throws NumberFormatException {
        // Testing the logic: if (expPos < decPos) throw NFE
        // This requires a string where 'e' index is smaller than '.' index
        NumberUtils.createNumber("1e.5");
    }

    @Test
    public void testCreateNumber_AllZerosLogic() throws NumberFormatException {
        // Test the "allZeros" branch for float/double precision check
        // 0.000000000000000000000000000000000000000000000000001
        assertTrue(NumberUtils.createNumber("0.000000000000000000000000000000000000000000000000001") instanceof BigDecimal);
        // 0.0 with no exponent
        assertTrue(NumberUtils.createNumber("0.0") instanceof Float);
    }

    @Test
    public void testCreateNumber_ComplexExponent() throws NumberFormatException {
        // Test trailing non-digit with exponent: "1.23e10f"
        assertTrue(NumberUtils.createNumber("1.23e10f") instanceof Float);
        assertTrue(NumberUtils.createNumber("1.23E10d") instanceof Double);
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidLongSuffix() throws NumberFormatException {
        // L suffix but contains decimal
        NumberUtils.createNumber("1.23L");
    }

    @Test
    public void testCreateNumber_LargeFloatInfinite() throws NumberFormatException {
        // Extremely large value that makes float infinite
        // Should fall through to Double or BigDecimal
        NumberUtils.createNumber("1e40f"); 
    }
}
